"""Campaign 12 machine-readable results: runs/c12/results12.json (+ runs/c12/summary12.md) from runs/c12/eval/*.json and the
ledgers. Every evaluated export (all seeds) is listed with its metrics, gates and cost-relevant sizes."""
import json, os, glob
ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."); E = os.path.join(ROOT, "runs", "c12", "eval")
L = lambda f: json.load(open(os.path.join(E, f))) if os.path.exists(os.path.join(E, f)) else {}
rows = []
for f in ("pilot.json", "main.json", "song.json"):
    for k, r in L(f).items():
        rows.append(dict(source=f, export=k, interval=None, err=r["all"]["err"], thirds=[x["err"] for x in r["thirds"]], worst16=r["worst16"], near_transitions=r["transitions"]["err_near"],
                         missed_fades=len(r["transitions"]["missed_fades"]), lag4_thirds=r["thirds_lag4"], thin_fg=r["thin"]["thin_fg_recall"], thin_bg=r["thin"]["thin_bg_recall"],
                         specks=r["small_cc"], blips=r["blips_spurious"], gates=r["gates"], file_bytes=r["file_bytes"], header=r["header"], replay=r["replay"], verify=r.get("verify")))
base = [dict(name=k, err=r["all"]["err"], worst16=r["worst16"], thin_fg=r["thin"]["thin_fg_recall"], thin_bg=r["thin"]["thin_bg_recall"], gates=r["gates"]) for k, r in L("baselines.json").items()]
rules = L("rules_pilot.json") + L("rules_L240.json") if isinstance(L("rules_pilot.json"), list) else []
gpu = [json.loads(l) for l in open(os.path.join(ROOT, "runs", "c12", "gpu_ledger.jsonl"))]; cpu = [json.loads(l) for l in open(os.path.join(ROOT, "runs", "c12", "cpu_ledger.jsonl"))]
out = dict(nca=rows, loophole_baselines=base, explicit_rules=rules, opening=L("opening_symmetry.json"), song=L("song_summary.json"),
           cost=dict(gpu_hours=round(sum(g["gpus"] * g["minutes"] for g in gpu) / 60, 2), gpu_jobs=gpu, cpu_core_hours=round(sum(c["cpu_s"] for c in cpu) / 3600, 2)))
json.dump(out, open(os.path.join(ROOT, "runs", "c12", "results12.json"), "w"), indent=1, default=float)
md = ["# Campaign 12 results (generated by experiments/summarize12.py from runs/c12/eval)", "",
      "| export | err | early/mid/late | worst16 | near transitions | thin fg/gap | blips | gates | bytes |", "|" + "---|" * 9]
for r in rows:
    md.append(f"| {r['export']} | {r['err']:.4f} | {' / '.join(f'{x:.4f}' for x in r['thirds'])} | {r['worst16']:.4f} | {r['near_transitions'] if r['near_transitions'] is None else round(r['near_transitions'], 4)} | "
              f"{r['thin_fg']:.2f}/{r['thin_bg']:.2f} | {r['blips']} | {'PASS' if r['gates']['success'] else 'fail ' + ','.join(k for k, v in r['gates'].items() if not v and k != 'success')} | {r['file_bytes']} |")
md += ["", "## Loophole baselines (built from the TRUE original; not replays)", "", "| baseline | err | worst16 | thin fg/gap | gates |", "|---|---|---|---|---|"]
md += [f"| {b['name']} | {b['err']:.4f} | {b['worst16']:.4f} | {b['thin_fg']:.2f}/{b['thin_bg']:.2f} | {'PASS' if b['gates']['success'] else 'fail'} |" for b in base]
md += ["", "## Explicit rules (dlrule-v1, autonomous execution)", "", "| interval | mode | k | K programs | max leaves | balance | rules | conditions | bytes | err | hold err | 1-step match |", "|" + "---|" * 12]
md += [f"| {r['spec']} | {r['mode']} | {r['k']} | {r['K']} | {r['max_leaves']} | {r.get('balance', 0)} | {r['complexity']['rules']} | {r['complexity']['conditions']} | {r['complexity']['file_bytes']} | {r['err']:.4f} | {r['hold_err']:.4f} | {sum(r['onestep_train_match']) / len(r['onestep_train_match']):.4f} |" for r in rules]
md += ["", f"GPU {out['cost']['gpu_hours']} GPU-h (assigned GPUs x runtime, summed per job); CPU {out['cost']['cpu_core_hours']} core-h."]
open(os.path.join(ROOT, "runs", "c12", "summary12.md"), "w").write("\n".join(md) + "\n"); print("\n".join(md[-3:]))
